// Generate the preloaded Judge-mode sample reports (SPEC.md: Judge mode
// — "Preloaded real reports: generated by real scans of our own sites,
// run by us against sites we own and may scan… They are scanner output,
// never hand assembled.").
//
// Usage:  node scripts/generate-samples.mjs
//
// Runs the app's own pipeline (createScan → one step per check group →
// finalizeReport) against each target below and writes the finalized
// report JSON to src/lib/sample-reports/<host>.json, where the samples
// API serves it as a labelled "Saved result".
//
// HONESTY GATE: a sample file is written only if the scan genuinely
// reached the target — at least one recorded HTTP response and at least
// one check that reached a verdict (Pass or Finding). If the environment
// blocks the scanner's direct connections (e.g. a sandbox whose resolver
// returns reserved addresses, or whose egress intercepts TLS), every
// check lands Inconclusive, the gate trips, NOTHING is written, and the
// script exits non-zero with the reason. An all-Inconclusive run is not
// a scan of the site and must never be shipped as one.
//
// Run this from an environment with ordinary direct egress: a developer
// machine, or the deployed app's host. The targets are the owner's own
// sites; scans are non-destructive and read-only, and run under the
// same policy the live app would apply (restricted/passive until the
// host is DNS-verified — the report's reproducibility stamp records
// exactly which policy and authorization state produced it).

import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { createScan, recordGroupResults } from '../src/lib/scanstore.js';
import { GROUPS, runGroup } from '../src/lib/scanner/index.js';
import { finalizeReport } from '../src/lib/pipeline.js';

const TARGETS = ['https://nyktos.tech', 'https://cliphaus.dev'];
const OUT_DIR = path.join(
  path.dirname(fileURLToPath(import.meta.url)),
  '..',
  'src',
  'lib',
  'sample-reports'
);

async function scanTarget(url) {
  const session = createScan({ url, attested: true, ip: 'sample-generation' });
  for (const g of GROUPS) {
    session.groupStatus[g.id] = 'running';
    const results = await runGroup(session.ctx, g.id);
    recordGroupResults(session, g.id, results);
  }
  const report = await finalizeReport(session);
  return { session, report };
}

function reachedTarget(session, report) {
  const requests = session.ctx.requests || [];
  const verdicts = report.results.filter((r) => r.outcome === 'pass' || r.outcome === 'finding');
  return { ok: requests.length > 0 && verdicts.length > 0, requests: requests.length, verdicts: verdicts.length };
}

let failures = 0;
await mkdir(OUT_DIR, { recursive: true });

for (const url of TARGETS) {
  const host = new URL(url).hostname;
  process.stdout.write(`Scanning ${url} … `);
  try {
    const { session, report } = await scanTarget(url);
    const gate = reachedTarget(session, report);
    const counts = {};
    for (const r of report.results) counts[r.outcome] = (counts[r.outcome] || 0) + 1;
    if (!gate.ok) {
      failures += 1;
      console.log('BLOCKED');
      console.log(
        `  Gate tripped: ${gate.requests} recorded HTTP responses, ${gate.verdicts} checks reached a verdict. ` +
          `Outcomes: ${JSON.stringify(counts)}.`
      );
      const sample = report.results.find((r) => r.outcome === 'inconclusive');
      if (sample) console.log(`  First blocker: ${sample.title} — ${sample.detail}`);
      console.log('  No sample file written (an unreachable-target run is not a scan of the site).');
      continue;
    }
    const file = path.join(OUT_DIR, `${host}.json`);
    await writeFile(file, JSON.stringify(report, null, 2) + '\n', 'utf8');
    console.log('OK');
    console.log(
      `  Wrote ${path.relative(process.cwd(), file)} — outcomes ${JSON.stringify(counts)}, ` +
        `policy ${report.scanPolicy}, stamp ${report.stamp.timestamp}, scanner ${report.stamp.scannerVersion}.`
    );
  } catch (err) {
    failures += 1;
    console.log('FAILED');
    console.log(`  ${err && err.message ? err.message : String(err)}`);
    console.log('  No sample file written.');
  }
}

if (failures > 0) {
  console.error(`\n${failures} of ${TARGETS.length} sample scans did not produce a report. See HACKATHON.md for the recorded blocker.`);
  process.exit(1);
}
console.log('\nAll sample reports generated.');
